import sys

def main():
    data = sys.stdin.read().split()
    n, s, t = int(data[0]), int(data[1]), int(data[2])
    w = int(data[3])
    ok = set(data[4:4 + w])
    best = abs(s - t)
    for x in range(1, n + 1):
        d = str(x)
        good = True
        for ch in d:
            if ch not in ok:
                good = False
                break
        if good:
            c = len(d) + 1 + abs(x - t)
            if c < best:
                best = c
    print(best)

main()

